/* Map panels are generated only on demand. Fog costs no world-render passes. */
const ExoSurveyUI=(()=>{
 const n=v=>Number(v).toFixed(1),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function graph(session){if(!session)return '<div class="survey-idle" aria-hidden="true"><i></i><span>接入现场测距仪</span></div>';const points=session.points.slice(0,2),min=Math.min(...points.map(p=>p.actual))-15,max=Math.max(...points.map(p=>p.actual))+15,y=v=>155-(v-min)/(max-min)*130;return `<svg viewBox="0 0 440 180" role="img" aria-label="实测标高与旧图标高的比较；调节补偿，使两条线重合"><path d="M40 25V155H410" fill="none" stroke="#617269"/><path d="M65 ${y(points[0].actual)}L375 ${y(points[1].actual)}" stroke="#afd2af" stroke-width="4"/><path id="survey-old-line" d="M65 ${y(points[0].old+session.trim)}L375 ${y(points[1].old+session.trim)}" stroke="#e2ae79" stroke-width="3" stroke-dasharray="7 5"/>${points.map((p,i)=>`<circle cx="${65+i*310}" cy="${y(p.actual)}" r="6" fill="#d8ebc1"/><text x="${65+i*310}" y="175" text-anchor="middle" fill="#b9c2ad" font-size="13">测点 ${i+1}</text>`).join('')}</svg>`;}
 function consoleHTML(id,session,message=''){
  const s=ExoSurvey.sites[id],done=ExoSurvey.calibrated(id),k=s.cargo,st=ExoSurvey.state,available=k&&!st.carrying.includes(k)&&!st.installed.includes(k);
  return `<section class="survey-console"><header><span>野外测绘 / ${String(id+1).padStart(2,'0')}</span><button onclick="Exo.closeSurvey()" aria-label="收起信标控制台">×</button></header><h2>${esc(s.name)}</h2><p>${done?'区域复测已写回地图。青色实线是修正后的道路；远方尚未复测的旧图仍需留心。':'旧地图的标高偏了。先读取两处实测值，转动补偿旋钮，让橙色虚线与青色实线重合。'}</p>${done?`<div class="survey-restored"><span>区域已揭开</span><strong>${esc(s.area)}</strong><small>道路 · 青灯 · 设施入口</small></div><p>${esc(s.detail)}</p>${available?`<button class="primary" onclick="Exo.surveyTake(${id})">打开检修柜 · 带走${ExoSurvey.cargo[k].name}</button>`:k?'<p class="survey-feedback">物资已'+(st.installed.includes(k)?'用在 K–09':'装进机甲侧箱')+'。</p>':''}<button onclick="Exo.travel()">看看更新后的地图</button><button onclick="Exo.trackCampaign()">继续沿路走 →</button>`:`<div id="survey-graph">${graph(session)}</div>${session?`<div class="survey-key"><span>━ 现场实测</span><span>┄ 旧图 + 补偿</span></div><label for="survey-trim">标高补偿 <output id="survey-trim-label">${n(session.trim)} m</output></label><input id="survey-trim" type="range" min="-12" max="12" step="0.5" value="${session.trim}" oninput="Exo.surveyTune(+this.value)"><div class="survey-nudge"><button onclick="Exo.surveyNudge(-.5)">降低 0.5 m</button><button onclick="Exo.surveyNudge(.5)">升高 0.5 m</button></div><p id="survey-error" class="survey-feedback" role="status">拟合偏差 ${n(ExoSurvey.error(session))} m</p><button id="survey-verify" class="primary" ${ExoSurvey.error(session)>.6?'disabled':''} onclick="Exo.surveyVerify()">用第三处测点核验并写回地图</button><small>第三处测点没有参与对齐。偏差需在 0.6 m 以内。</small>`:'<button class="primary" onclick="Exo.surveySample()">读取现场扫描 · 12 机甲能量</button><small>扫描只在信标旁进行。机甲能量会随休息恢复。</small>'}`}${message?`<p class="survey-feedback" role="status">${esc(message)}</p>`:''}</section>`;
 }
 function update(session){const q=id=>document.getElementById(id);if(!session||!q('survey-graph'))return;q('survey-graph').innerHTML=graph(session);q('survey-trim').value=session.trim;q('survey-trim-label').textContent=n(session.trim)+' m';q('survey-error').textContent='拟合偏差 '+n(ExoSurvey.error(session))+' m';q('survey-verify').disabled=ExoSurvey.error(session)>.6;}
 function refugeHTML(message=''){const st=ExoSurvey.state;return `<section class="survey-console refuge-console"><header><span>K–09 / 回来的人</span><button onclick="Exo.closeSurvey()" aria-label="收起维修间面板">×</button></header><h2>门口给你留了位置</h2><p>把东西卸在老林的工作台旁。灯路通向远处，这里收下你带回来的东西。</p><div class="refuge-changes">${Object.entries(ExoSurvey.cargo).map(([k,c])=>`<div class="${st.installed.includes(k)?'is-repaired':''}"><span>${st.installed.includes(k)?'✓':st.carrying.includes(k)?'↓':'·'}</span><div><h3>${c.title}</h3><p>${st.installed.includes(k)?c.after:st.carrying.includes(k)?c.name+'已装在机甲侧箱，随时可以交付。':k==='filter'?'通风口还盖着积灰的防尘布。':k==='valve'?'育苗槽还缺一只密封阀。': '雨棚下的空地，可以再铺两张床。'}</p></div></div>`).join('')}</div>${st.carrying.length?'<button class="primary" onclick="Exo.refugeDeliver()">卸下物资，一起修好它</button>':''}<button onclick="Exo.refugeRest()">停靠休整 · 修复装甲并保存</button><button onclick="Exo.refugeEnter()">进维修间看看</button><button onclick="Exo.trackCampaign()">再出发 →</button>${message?`<p class="survey-feedback" role="status">${esc(message)}</p>`:''}</section>`;}
 // Voronoi cells use the same nine camp locations as world navigation. Adjacent
 // regions meet exactly; no overlapping circles leak undiscovered POIs.
 function cell(index,camps,W,H){let poly=[{x:0,y:0},{x:W,y:0},{x:W,y:H},{x:0,y:H}],a=camps[index];for(let j=0;j<camps.length;j++){if(j===index)continue;const b=camps[j],dx=b.x-a.x,dy=b.y-a.y,limit=(b.x*b.x+b.y*b.y-a.x*a.x-a.y*a.y)/2,side=p=>p.x*dx+p.y*dy-limit,out=[];for(let i=0;i<poly.length;i++){const p=poly[i],q=poly[(i+1)%poly.length],v=side(p),w=side(q);if(v<=0)out.push(p);if((v<=0)!==(w<=0)){const t=v/(v-w);out.push({x:p.x+(q.x-p.x)*t,y:p.y+(q.y-p.y)*t});}}poly=out;}return poly;}
 function atlas(u,campaign){const W=ExoWorld,S=ExoSurvey,sx=x=>x/W.surfaceWidth*700,sy=y=>y/W.surfaceHeight*465,line=ps=>ps.map(p=>`${n(sx(p.x))},${n(sy(p.y))}`).join(' '),o=campaign?.objective(),st=S.state;
  const cells=W.surfaceCamps.map((c,i)=>({i,points:line(cell(i,W.surfaceCamps,W.surfaceWidth,W.surfaceHeight))}));
  const masks=cells.filter(c=>S.known(c.i)).map(c=>`<polygon points="${c.points}" fill="white"/>`).join('')+st.visited.map(i=>{const c=W.surfaceCamps[i];return `<circle cx="${sx(c.x)}" cy="${sy(c.y)}" r="9" fill="white"/>`;}).join('');
  const roads=W.roads.map(r=>`<polyline points="${line(r.points)}" fill="none" stroke="#98c7b3" stroke-width="2"/>`).join('');
  const home=S.home,knowsHome=campaign?.state.done.includes('refuge'),nav=W.navigation(u);
  const svg=`<svg class="survey-world-map" viewBox="-10 -10 720 485" role="img" aria-label="六座信标的区域地图；灰色为未经复测的旧图，青色为已校准的道路和路灯"><defs><pattern id="survey-hatch" width="12" height="12" patternUnits="userSpaceOnUse"><path d="M0 12L12 0" stroke="#9c9e91" stroke-opacity=".08"/></pattern><mask id="survey-known"><rect width="700" height="465" fill="black"/>${masks}</mask></defs><rect width="700" height="465" fill="#16232a"/><rect width="700" height="465" fill="url(#survey-hatch)"/>${cells.map(c=>`<polygon points="${c.points}" fill="${S.known(c.i)?'#759b7522':'#0b131d55'}" stroke="#76867722"/>`).join('')}<g transform="translate(5 -4)" opacity=".28" stroke-dasharray="3 6">${roads}</g><g mask="url(#survey-known)">${roads}${W.beacons.map(p=>`<circle cx="${sx(p.x)}" cy="${sy(p.y)}" r="1.5" fill="#c7dbab"/>`).join('')}${W.structures.filter(s=>S.known(s.sector)).map(s=>`<rect x="${sx(s.entrance.x)-2}" y="${sy(s.entrance.y)-2}" width="4" height="4" fill="#e5ba82"/>`).join('')}${W.caves.map(c=>`<circle cx="${sx(c.x)}" cy="${sy(c.y)}" r="3" fill="#ddab78"/>`).join('')}</g>${S.sites.map(s=>`<a href="#" onclick="event.preventDefault();Exo.surveyTrack(${s.id})" aria-label="前往${s.name}${S.calibrated(s.id)?'，已校准':'，待复测'}"><path d="M${sx(s.x)} ${sy(s.y)-10}l8 14h-16z" fill="${S.calibrated(s.id)?'#afd9b2':'#24353b'}" stroke="${S.calibrated(s.id)?'#dff1c3':'#d0b98a'}" stroke-width="2"/><text x="${sx(s.x)+(s.id>=4?-12:12)}" y="${sy(s.y)+4}" text-anchor="${s.id>=4?'end':'start'}" fill="#d5d6bb" font-size="18">${s.id+1} · ${s.name}</text></a>`).join('')}${knowsHome?`<path d="M${sx(home.x)-5} ${sy(home.y)+5}v-8l5-5 5 5v8z" fill="#e6bf86"/><text x="${sx(home.x)+11}" y="${sy(home.y)-6}" fill="#e6bf86" font-size="12">K–09 · 归处</text>`:''}${nav?`<polyline points="${line(nav.route.points)}" fill="none" stroke="#f0c380" stroke-width="2.5" stroke-dasharray="6 3"/>`:''}<circle cx="${sx(u.x)}" cy="${sy(u.y)}" r="5" fill="#fff4d4" stroke="#0d191e" stroke-width="2"/></svg>`;
  if(campaign&&!campaign.state.finished)return `<div class="fc-panel survey-atlas"><div class="fc-eyebrow">随身路线图 / 沿青灯走</div><section class="survey-next"><small>眼前的下一步</small><h3>${esc(o.title)}</h3><p>${esc(o.instruction)}</p><button class="primary" onclick="Exo.trackCampaign()">${esc(o.label)} →</button></section>${ExoStoryMap.panel(u,campaign)}<details><summary>远方的旧图 · 六座信标与待复测地区</summary><p>远方的灰线还没有核实。先沿眼前的灯找到人，之后再把这些地方一段段补回来。</p>${svg}</details><button class="primary" onclick="closeModal()">收好地图，继续驾驶</button></div>`;
  return `<div class="fc-panel survey-atlas"><div class="fc-eyebrow">手绘补记 / 旧图仍有误差</div><h2>这张旧图，正在变准</h2><p>灰线是未核实的旧路。校准信标，补上真实道路与入口；路面危险仍需现场判断。</p>${svg}<p class="survey-key"><span>△ 待复测信标</span><span>▲ 已校准</span><span>┄ 旧图 / 未确认</span><span>━ 实测道路</span><span>● 你在这里</span></p>${o?`<section class="survey-next"><small>现在可以做的事</small><h3>${esc(o.title)}</h3><p>${esc(o.instruction)}</p><button class="primary" onclick="Exo.trackCampaign()">${esc(o.label)} →</button></section>`:''}<div class="survey-sites">${S.sites.map(s=>`<button onclick="Exo.surveyTrack(${s.id})"><small>${S.calibrated(s.id)?'已校准 · '+s.area:'旧图标记 · 地貌待复测'}</small><strong>${s.id+1} / ${s.name}</strong><span>${S.calibrated(s.id)?'查看归路':'沿路前往'} ↗</span></button>`).join('')}</div>${typeof ExoStoryMap!=='undefined'?'<details '+(!campaign?.state.finished?'open':'')+'><summary>K–09 随身路线图 · 当前青灯方向</summary>'+ExoStoryMap.panel(u,campaign)+'</details>':''}<button onclick="Exo.wildsMap()">河谷、旧桥与山路 · 随身勘测图</button><details><summary>已经走到过的营地 · 快速返程</summary><div class="fc-buttons">${W.surfaceCamps.map((c,i)=>S.canReturn(i)?`<button onclick="closeModal();Exo.jump(${i})">${c.name}</button>`:'').join('')||'<p>亲自抵达营地后，这里会留下一张返程便签。</p>'}</div></details><details><summary>已复测的设施与洞口</summary><div class="fc-buttons">${W.structures.filter(s=>S.known(s.sector)).map(s=>`<button onclick="Exo.surveyFacility('${s.id}')">${esc(s.name)}</button>`).join('')||'<p>信标校准后，这里会补上实际入口的位置。</p>'}${W.caves.filter(c=>S.known(c.id==='basalt'?5:6)).map(c=>`<button onclick="Exo.surveyCave('${c.id}')">${esc(c.name)} · 地下入口</button>`).join('')}</div></details><button class="primary" onclick="Exo.closeSurvey();closeModal()">收好地图，继续驾驶</button></div>`;
 }
 return {consoleHTML,refugeHTML,update,atlas,cell};
})();
